mkdir -p /tmp/edge && cat > /tmp/edge/main.rs <<'EOF'
use accumulate::map;

fn main() {
    // empty
    let e: Vec<i32> = vec![];
    assert_eq!(map(e, |x| x * 2), Vec::<i32>::new());

    // preserving order and capacity for large input
    let big: Vec<i32> = (0..100_000).collect();
    let doubled: Vec<i64> = map(big.clone(), |x| i64::from(x) * 2);
    assert_eq!(doubled.len(), 100_000);
    assert_eq!(doubled[12345], 24690);
    assert_eq!(doubled[99999], 199998);

    // consuming non-Copy values
    let strings = vec!["a".to_string(), "b".to_string()];
    let lens: Vec<usize> = map(strings, |s| s.len());
    assert_eq!(lens, vec![1, 1]);

    // FnOnce capturing closure
    let consumed = String::from("owned");
    let out: Vec<String> = map(vec![1, 2], move |x| format!("{}{}", consumed, x));
    assert_eq!(out, vec!["owned1", "owned2"]);

    println!("edge cases ok");
}
EOF
